tfns={'id':lambda x:x,'r9':lambda x:np.rot90(x,1),'r18':lambda x:np.rot90(x,2),'r27':lambda x:np.rot90(x,3),'fud':np.flipud,'flr':np.fliplr}
def solve(grid):
    G=np.array(grid)
    blks=comps6(G.tolist())
    out=G.copy()
    for b in blks:
        rs=[p[0] for p in b]; cs=[p[1] for p in b]
        r0,c0=min(rs),min(cs); bh=max(rs)-r0+1; bw=max(cs)-c0+1
        s=tfns['flr'](G)[r0:r0+bh,c0-2:c0-2+bw]
        ok = c0>=2 and s.shape[1]==bw and 6 not in s.ravel()
        if ok:
            out[r0:r0+bh,c0:c0+bw]=s; continue
        best=None
        for nm,fn in tfns.items():
            c=fn(G)
            for i in range(c.shape[0]-bh+1):
                for j in range(c.shape[1]-bw+1):
                    s2=c[i:i+bh,j:j+bw]
                    if 6 in s2.ravel(): continue
                    off=(abs(i-r0)+abs(j-c0))
                    if best is None or off<best[0]: best=(off,nm,s2)
        _,_,s2=best
        out[r0:r0+bh,c0:c0+bw]=s2
    return out
for n in [1,2,3,4]:
    Ia=np.array(G[f'Demo pair {n} input']); O=np.array(G[f'Demo pair {n} output'])
    print(n,(solve(Ia)==O).all().item())
res=solve(G['Test input'])
